  edit('Template ID',['id']);const kind=edit('Story beat',['kind'],'text',[['event','Event or invitation'],['obstacle','Obstacle or rival'],['goal','Goal with deadline'],['temptation','Temptation']]);kind.addEventListener('change',()=>{if(kind.value==='goal')p.directorTemplates[i].goal||={deadlineTicks:12};render();});edit('How it arrives',['delivery'],'text',[['offer','Player can accept it'],['incident','Director starts it']]);edit('Tone level',['tone'],'text',[['1','Grounded'],['2','Soap opera'],['3','High stakes melodrama']]);edit('Scene title',['scene','title']);edit('Opening',['scene','opening'],'long');
  if(template.roles?.lead?.pool){const lead={value:template.roles.lead.pool[0]||''},input=field(form,lead,'value','Lead character','text',actors().filter(([id])=>id!==p.playerId));input.oninput=()=>{p.directorTemplates[i].roles.lead.pool=[input.value];p.directorTemplates[i].reviewStatus='pending';json.value=JSON.stringify(p.directorTemplates[i],null,2);message('Template changed. Review it again before publishing.');};}
  const repeat={value:template.scene.repeatable?'yes':'no'},repeatInput=field(form,repeat,'value','May recur after its normal uses?','text',[['no','One-time scene'],['yes','Reuse when the library runs dry']]);repeatInput.oninput=()=>{p.directorTemplates[i].scene.repeatable=repeatInput.value==='yes';p.directorTemplates[i].reviewStatus='pending';json.value=JSON.stringify(p.directorTemplates[i],null,2);message('Template changed. Review it again before publishing.');};
