  const preview=node('div');const inspect=node('button','Check and preview castings');inspect.type='button';inspect.onclick=async()=>{try{const candidate=JSON.parse(json.value);candidate.reviewStatus='pending';const result=await api('/api/studio/director/preview',{pack:p,template:candidate});p.directorTemplates[i]=candidate;preview.replaceChildren();for(const scene of result.scenes){const row=node('article');row.className='studio-card';row.append(node('strong',scene.title||scene.id),node('p',scene.opening||''),node('small',Object.entries(scene.roles).map(([role,id])=>`${role}: ${id}`).join(' · ')));for(const choice of scene.choices)row.append(node('p',`${choice.label||choice.id} → ${choice.result||''} · ${(choice.effects||[]).map(e=>e.type).join(', ')||'no effect'}`));preview.append(row);}message(`${result.scenes.length} casting${result.scenes.length===1?'':'s'} ready for review.`);}catch(e){fail(e);}};
