const $=id=>document.getElementById(id);let draft=null,proposal=null,review=null,forceApply=false,moduleCatalog={},aiSceneCandidate=null,aiSceneBrief={purpose:'',location:'',characters:'',tone:'',continuity:''},aiCharacterCandidate=null,aiCharacterBrief={name:'',pronouns:'she/her',age:21,location:'',brief:''},expandedSections=new Set(['Game project','Locations','Characters','Scripted scenes']);
const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const v=await r.json();if(!r.ok)throw Error(v.error||'Request failed');return v;}
function message(s){$('studio-status').textContent=s;}
function fail(e){message(e.message);}
function showPlaytest(report){const box=$('playtest-report');box.hidden=false;box.replaceChildren();box.append(node('h2','Route test report'),node('p',`${report.summary.runs} deterministic routes · ${report.summary.critical} critical · ${report.summary.warnings} warnings · ${report.summary.neverCompleted} scenes never completed`));if(report.storyGraph?.dependencies.length){box.append(node('h3','Story prerequisites'));const links=node('div');links.className='playtest-coverage';for(const link of report.storyGraph.dependencies){const row=node('div');row.className='playtest-row';row.append(node('strong',link.scene),node('span',`Unlocks after ${link.requires}`));links.append(row);}box.append(links);}if(report.graphs?.length){box.append(node('h3','Scene paths'));const graphs=node('div');graphs.className='playtest-coverage';for(const graph of report.graphs){const row=node('div');row.className='playtest-row';const path=graph.edges.map(edge=>`${edge.from} → ${edge.to||'finish'}`).join(' · ')||'No choices';row.append(node('strong',graph.title||graph.scene),node('span',path),node('small',`${graph.nodes.length} step${graph.nodes.length===1?'':'s'} · ${graph.terminalNodes.length} ending point${graph.terminalNodes.length===1?'':'s'}`));if(graph.unreachable.length)row.append(node('small',`Unreachable: ${graph.unreachable.join(', ')}`));if(graph.noTerminalPath.length)row.append(node('small',`Cannot finish from: ${graph.noTerminalPath.join(', ')}`));graphs.append(row);}box.append(graphs);}if(report.coverage.length){box.append(node('h3','Route coverage'));const table=node('div');table.className='playtest-coverage';for(const scene of report.coverage){const row=node('div');row.className='playtest-row';row.append(node('strong',scene.title||scene.scene),node('span',`${scene.completed}/${report.summary.runs} completed · ${scene.active} active · ${scene.paused} paused`));table.append(row);}box.append(table);}const findings=node('div');for(const finding of report.findings){const row=node('article');row.className=`playtest-finding severity-${finding.severity}`;row.append(node('strong',`${finding.severity.toUpperCase()} · ${finding.code}`),node('p',finding.message),node('small',`Observed in ${finding.runs} route${finding.runs===1?'':'s'}${finding.scene?` · scene ${finding.scene}`:''}`));findings.append(row);}if(!report.findings.length)findings.append(node('p','No route problems were detected.'));box.append(findings);box.scrollIntoView({behavior:'smooth',block:'start'});}
function option(select,value,label){const o=node('option',label);o.value=value;select.append(o);}
async function refresh(){const [d,b]=await Promise.all([api('/api/studio/list'),api('/api/bootstrap')]);moduleCatalog=b.modules||{};$('draft-list').replaceChildren();option($('draft-list'),'','Open a draft…');for(const x of d.drafts)option($('draft-list'),x.id,x.title+' · '+new Date(x.updated).toLocaleDateString());$('clone').replaceChildren();option($('clone'),'','Copy a game project…');for(const p of b.packs)option($('clone'),p.id,p.title);}
function field(parent,obj,key,label,kind='text',choices){const wrap=node('label');wrap.className='studio-field';wrap.append(node('span',label));let input;if(choices){input=node('select');for(const [v,l] of choices)option(input,v,l);}else input=node(kind==='long'?'textarea':'input');if(kind==='number')input.type='number';input.value=obj[key]??'';input.oninput=()=>{obj[key]=kind==='number'?Number(input.value):input.value;message('Unsaved changes');};wrap.append(input);parent.append(wrap);return input;}
async function preparedImage(file,kind){if(file.size>20000000)throw Error('Choose an image file smaller than 20 MB.');const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});try{if(bitmap.width>8192||bitmap.height>8192||bitmap.width*bitmap.height>40000000)throw Error('This image is too large to process safely. Resize it below 40 megapixels first.');const canvas=document.createElement('canvas');if(kind==='background'){canvas.width=1920;canvas.height=1080;const sourceRatio=bitmap.width/bitmap.height,targetRatio=16/9;let sx=0,sy=0,sw=bitmap.width,sh=bitmap.height;if(sourceRatio>targetRatio){sw=bitmap.height*targetRatio;sx=(bitmap.width-sw)/2;}else{sh=bitmap.width/targetRatio;sy=(bitmap.height-sh)/2;}canvas.getContext('2d',{alpha:false}).drawImage(bitmap,sx,sy,sw,sh,0,0,1920,1080);for(const quality of [.9,.84,.78,.72,.66]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=3500000)return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not prepare image.'));reader.readAsDataURL(blob);});}throw Error('This background is still too large after resizing. Try a simpler or lower-detail image.');}
if(kind==='character'){if(file.type!=='image/png')throw Error('Character art must be a PNG with transparency.');const check=document.createElement('canvas');check.width=512;check.height=512;const checkCtx=check.getContext('2d',{willReadFrequently:true});checkCtx.clearRect(0,0,512,512);checkCtx.drawImage(bitmap,0,0,512,512);const pixels=checkCtx.getImageData(0,0,512,512).data;let transparent=false;for(let i=3;i<pixels.length;i+=4)if(pixels[i]<250){transparent=true;break;}if(!transparent)throw Error('This PNG has no transparent pixels. Remove its background, then upload it again.');canvas.width=1024;canvas.height=1536;const scale=Math.min(1024/bitmap.width,1536/bitmap.height),w=Math.round(bitmap.width*scale),h=Math.round(bitmap.height*scale);canvas.getContext('2d').clearRect(0,0,1024,1536);canvas.getContext('2d').drawImage(bitmap,(1024-w)/2,(1536-h)/2,w,h);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob||blob.size>3500000)throw Error('The prepared character PNG exceeds 3.5 MB. Reduce its detail or resize the source image.');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not prepare image.'));reader.readAsDataURL(blob);});}throw Error('Unknown image type.');}finally{bitmap.close();}}
function imageUpload(parent,obj,key,label,kind){const wrap=node('div');wrap.className='studio-field';wrap.append(node('span',label));const help=kind==='background'?'Recommended: 16:9 landscape. The builder center-crops and resizes to 1920 × 1080 JPEG.':'Transparent PNG only. The builder fits the character onto a 1024 × 1536 transparent canvas.';const hint=node('small',help);hint.className='asset-hint';wrap.append(hint);const row=node('div');row.className='studio-image '+kind;if(obj[key]){const preview=node('img');preview.src=obj[key];preview.alt='';row.append(preview);}const input=node('input');input.type='file';input.accept=kind==='character'?'image/png': 'image/png,image/jpeg,image/webp';input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;message('Preparing image…');const data=await preparedImage(file,kind);const result=await api('/api/studio/asset',{data,kind});obj[key]=result.path;render();message(kind==='background'?'Background cropped to 16:9 and optimized.':'Character art prepared as a transparent PNG.');}catch(e){fail(e);}finally{input.value='';}};row.append(input);if(obj[key]){const clear=node('button','Remove');clear.onclick=()=>{delete obj[key];render();message('Unsaved changes');};row.append(clear);}wrap.append(row);parent.append(wrap);}
const list=s=>s.split(',').map(x=>x.trim()).filter(Boolean);
function csv(parent,obj,key,label){const temp={value:(obj[key]||[]).join(', ')};const input=field(parent,temp,'value',label);input.oninput=()=>{obj[key]=list(input.value);message('Unsaved changes');};}
