function moduleEditor(){const s=section('Gameplay modules','Compose each game from small systems. Dependencies enable automatically; turning a system off also turns off its dependants. Data stays in the project when a system is disabled.');for(const meta of Object.values(moduleCatalog)){const row=node('div');row.className='module-row';const check=node('input');check.type='checkbox';check.checked=!!draft.pack.modules[meta.id];check.onchange=()=>setModule(meta.id,check.checked);const text=node('div');text.append(node('strong',meta.title),node('p',meta.description));if(meta.requires?.length)text.append(node('small','Needs: '+meta.requires.map(id=>moduleCatalog[id]?.title||id).join(', ')));row.append(check,text);s.append(row);}}
