 const roll=node('button','⚄ Surprise me');roll.type='button';roll.onclick=()=>{aiCharacterBrief={...aiCharacterBrief,name:pick(suggestedNames),brief:pick(characterSeeds)};render();message('New name and character brief suggested.');};const generate=node('button',aiCharacterCandidate?'Generate another profile':'Generate profile');generate.type='button';generate.onclick=async()=>{try{const text=aiCharacterBrief.brief.trim()||brief.placeholder;generate.disabled=true;message('Designing a structured character profile…');const result=await api('/api/studio/ai-character',{pack:p,...aiCharacterBrief,brief:text});aiCharacterCandidate=result.character;render();message(`Character profile drafted by ${result.provider}. Review it before adding.`);}catch(e){fail(e);}finally{generate.disabled=false;}};box.append(roll,generate);
 if(aiCharacterCandidate){const c=node('article');c.className='studio-card character-candidate';c.append(node('h3',aiCharacterCandidate.name),node('p',aiCharacterCandidate.description),node('p',aiCharacterCandidate.personality),node('small',`${aiCharacterCandidate.pronouns} · age ${aiCharacterCandidate.age} · ${aiCharacterCandidate.major||'No occupation set'} · ${aiCharacterCandidate.location}`));const json=node('textarea');json.className='ai-character-json';json.spellcheck=false;json.value=JSON.stringify(aiCharacterCandidate,null,2);c.append(node('p','Review every field. You may edit the JSON before adding it.'),json);const read=()=>{const value=JSON.parse(json.value);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Candidate must be one character object.');return value;};const accept=node('button','Approve and add to cast');accept.onclick=async()=>{try{const actor=read(),pack=structuredClone(p);pack.actors.push(actor);await api('/api/studio/validate',{pack});p.actors.push(actor);aiCharacterCandidate=null;aiCharacterBrief={name:'',pronouns:'she/her',age:21,location:p.locations[0]?.id||'',brief:''};render();message(`${actor.name} added to the unsaved cast. Add art, schedules, and relationship data if needed, then save.`);}catch(e){fail(e);}};const discard=node('button','Discard');discard.onclick=()=>{aiCharacterCandidate=null;render();message('Character candidate discarded.');};c.append(accept,discard);box.append(c);}s.append(box);
