$('new').onclick=async()=>{try{draft=await api('/api/studio/create',{});render();message('New draft. Edit the sections, then save.');await refresh();}catch(e){fail(e);}};
$('clone-button').onclick=async()=>{try{if(!$('clone').value)throw Error('Choose a sample first.');draft=await api('/api/studio/create',{packId:$('clone').value});render();message('Sample copied into your own draft.');await refresh();}catch(e){fail(e);}};
$('open').onclick=async()=>{try{draft=await api('/api/studio/get?id='+encodeURIComponent($('draft-list').value));render();message('Draft opened.');}catch(e){fail(e);}};
$('save').onclick=async()=>{try{draft=await api('/api/studio/save',draft);render();message('Draft saved.');await refresh();}catch(e){fail(e);}};
$('check').onclick=async()=>{try{await api('/api/studio/validate',{pack:draft.pack});message('Scenario is valid and ready to publish.');}catch(e){fail(e);}};
$('playtest').onclick=async()=>{try{$('playtest').disabled=true;message('Testing every opening with three deterministic routes…');const report=await api('/api/studio/playtest',{pack:draft.pack,turns:50});showPlaytest(report);message(report.summary.critical?'Route test found critical problems. Review the report before publishing.':`Route test complete: ${report.summary.runs} routes checked.`);}catch(e){fail(e);}finally{$('playtest').disabled=false;}};
$('publish').onclick=async()=>{try{draft=await api('/api/studio/save',draft);const p=await api('/api/studio/publish',{id:draft.id});message('Published '+p.title+'. Opening the scenario picker…');setTimeout(()=>location.assign('/'),700);}catch(e){fail(e);}};
$('apply-json').onclick=()=>{try{draft.pack=JSON.parse($('json').value);render();message('JSON applied. Save the draft or check for errors.');}catch(e){fail(e);}};
$('export-pack').onclick=async()=>{try{const pack=structuredClone(draft.pack),paths=[...new Set([...pack.locations.map(x=>x.background),...pack.actors.map(x=>x.portrait),...pack.actors.flatMap(x=>(x.poses||[]).map(p=>p.image))].filter(x=>x?.startsWith('scenario-media/')))],media={};for(const path of paths)media[path]=await api('/api/studio/asset?path='+encodeURIComponent(path));const data={format:'story-framework-game-project',version:1,pack,media};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=node('a');a.href=url;a.download=(pack.title||'game-project').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Project exported, including its uploaded art.');}catch(e){fail(e);}};
$('import-project').onchange=async e=>{try{const file=e.target.files?.[0];if(!file)return;const data=JSON.parse(await file.text()),pack=data.pack||data;draft=await api('/api/studio/create',{});const remap={};for(const [old,asset] of Object.entries(data.media||{})){const result=await api('/api/studio/asset',{data:`data:${asset.mime};base64,${asset.data}`});remap[old]=result.path;}for(const entry of [...(pack.locations||[]),...(pack.actors||[]),...(pack.actors||[]).flatMap(a=>a.poses||[])])for(const key of ['background','portrait','image'])if(remap[entry[key]])entry[key]=remap[entry[key]];draft.pack=pack;draft=await api('/api/studio/save',draft);render();message('Game project imported. Save changes and publish when ready.');await refresh();}catch(err){fail(err);}finally{e.target.value='';}};
$('load-proposal').onchange=async e=>{try{const file=e.target.files?.[0];if(!file)return;proposal=JSON.parse(await file.text());forceApply=false;message('Checking the drafts and running the bot playtest…');await reviewDrafts();}catch(err){proposal=review=null;fail(err);}finally{e.target.value='';}};
refresh().catch(fail);
